/** One currency in circulation, with its ISO 4217 code where Wikidata has one. */
export interface CountryCurrency {
  /** ISO 4217 alphabetic code, for example "EUR". Absent for a few local currencies. */
  code?: string;
  /** English name of the currency. */
  name?: string;
}

/** A country or territory holding an ISO 3166-1 alpha-2 code. */
export interface Country {
  /** Wikidata entity id, for example "Q142". */
  qid: string;
  /** English label, for example "France". */
  name: string;
  /** Official long form (P1448), for example "French Republic". */
  officialName?: string;
  /** ISO 3166-1 alpha-2 code, for example "FR". Unique across this array. */
  iso2: string;
  /** ISO 3166-1 alpha-3 code, for example "FRA". */
  iso3?: string;
  /** ISO 3166-1 numeric code as a zero padded string, for example "250". */
  isoNumeric?: string;
  /** International calling codes, for example ["+33"]. Sorted. */
  callingCodes: string[];
  /** Currencies in circulation. Sorted by ISO 4217 code. */
  currencies: CountryCurrency[];
  /** Country code top level domains, for example [".fr"]. Sorted. */
  tlds: string[];
  /** Standard time UTC offsets, for example ["UTC+01:00"]. Sorted west to east. */
  timeZones: string[];
  /** IANA zone identifiers where Wikidata records them. Not parallel to timeZones. */
  ianaTimeZones: string[];
  /** Side of the road traffic drives on, "right" or "left". */
  drivingSide?: string;
  /** Domestic mains plug types, for example ["Type C", "Type E"]. Sorted. */
  plugTypes: string[];
  /** English label of the capital city. */
  capital?: string;
  /** English label of the continent. One value even when Wikidata lists two. */
  continent?: string;
  /** Most recent recorded population. */
  population?: number;
  /** Total area in square kilometres. */
  areaKm2?: number;
  /** Regional indicator flag emoji derived from the alpha-2 code. */
  flagEmoji?: string;
  /** English Wikipedia article title. */
  wikipedia?: string;
  /** Demonym in English, for example "French". */
  demonym?: string;
}

